test('recordLogin sets last_login_at on the active user', (t, done) => {
  const before = Date.now();
  recordLogin('ada@example.com', (err, user) => {
    assert.equal(err, null);
    assert.equal(user.id, 1);
    const at = Date.parse(user.last_login_at);
    assert.ok(at >= before && at <= Date.now());
    done();
  });
});

test('recordLogin calls back with null for soft-deleted or unknown users', (t, done) => {
  recordLogin('alan@example.com', (err, user) => {
    assert.equal(err, null);
    assert.equal(user, null);
    recordLogin('nobody@example.com', (err2, user2) => {
      assert.equal(err2, null);
      assert.equal(user2, null);
      done();
    });
  });
});
EOF
